import { useState,useEffect } from "react";
import Dashboard from "./pages/AdminComponent/Dashboard";
import Tourists from "./pages/AdminComponent/Tourists";
import TourGuides from "./pages/AdminComponent/TourGuides";
import Vehicles from "./pages/AdminComponent/Vehicles";
import Accommodation from "./pages/AdminComponent/Accommodation";
import AccommodationLoginDetails from "./pages/AccommodationLoginDetails";
import DevotionalContent from "./pages/AdminComponent/DevotionalContent";
import TouristSpots from "./pages/AdminComponent/TouristSpots";
import ChargesPricing from "./pages/AdminComponent/ChargesPricing";
import Landing from "./pages/LandingPageComponent/Landing";
import Login from "./pages/AdminComponent/Login";
import Register from "./pages/AdminComponent/Register";
import CustomerLogin from "./pages/CustomerComponent/CustomerLogin";
import CustomerRegister from "./pages/CustomerComponent/CustomerRegister";
import "./App.css";
// import CustomerDashboard from "./pages/CustomerLogin";
import PilgrimHome from "./pages/CustomerComponent/Customer_Dashboard";
import TourGuideLogin from "./pages/TourGuideComponent/TourGuideLogin";
import VehicleLogin from "./pages/VehicleComponent/VehicleLogin";
import DriverLogin from "./pages/DriverComponent/DriverLogin";
import TouriestGuide from "./pages/TourGuideComponent/TouriestGuide";
import VahicleLoginDetails from "./pages/VehicleComponent/VahicleLoginDetails";
import DriverLoginDetails from "./pages/DriverComponent/DriverLoginDetails";
import AIAssistant from "./pages/CustomerComponent/AIassistant";
import TourGuideRegistration from "./pages/TourGuideComponent/TourGuideRegistration";
import VehicleRegistration from "./pages/VehicleComponent/VehicleRegistration";
import DriverManagement from "./pages/DriverComponent/DriverManagement";
// import AIFeatures from "./pages/AIfeatures";
import AccommodationLogin from "./pages/AccomendationComponent/AccommodationLogin";
import AccommodationRegistration from "./pages/AccomendationComponent/AccommodationRegistration";

// ─── Navigation config ────────────────────────────────────────────────────────
const NAV = [
  {
    section: "Overview",
    items: [
      { key: "dashboard", label: "Dashboard", icon: "ti-layout-dashboard" },
    ],
  },
  {
    section: "Management",
    items: [
      { key: "tourists",      label: "Tourists",       icon: "ti-users"    },
      { key: "tourGuides",    label: "Tour Guides",    icon: "ti-license"  },
      { key: "vehicles",      label: "Vehicles",       icon: "ti-car"      },
      { key: "accommodation", label: "Accommodation",  icon: "ti-building" },
      { key: "touristSpots",  label: "Tourist Spots",  icon: "ti-map-pin"  },
    ],
  },
  {
    section: "Services",
    items: [
      { key: "devotionalContent", label: "Devotional Content", icon: "ti-music" },
    ],
  },
  {
    section: "System",
    items: [
      { key: "chargesPricing", label: "Charges & Pricing", icon: "ti-cash" },
       { key: "AIFeatures", label: "AI Features", icon: "ti-cash" },
    ],
  },
  
];

const SCREEN_MAP = {
  dashboard:         <Dashboard />,
  tourists:          <Tourists />,
  tourGuides:        <TourGuides />,
  vehicles:          <Vehicles />,
  accommodation:     <Accommodation />,
  devotionalContent: <DevotionalContent />,
  touristSpots:      <TouristSpots />,
  chargesPricing:    <ChargesPricing />,
  // AIFeatures:    <AIFeatures />
};

const TITLES = {
  dashboard:         "Dashboard",
  tourists:          "Tourist Management",
  tourGuides:        "Tour Guide Management",
  vehicles:          "Vehicle & Transport Management",
  accommodation:     "Accommodation & Cottage Management",
  touristSpots:      "Tourist Spot Configuration",
  devotionalContent: "Devotional Content Management",
  chargesPricing:    "Charges & Pricing",
  // AIFeatures:    "AI/ML Features",
};

// ─── ROOT APP ─────────────────────────────────────────────────────────────────
export default function App() {
const [screen, setScreen] = useState("landing");

useEffect(() => {
  localStorage.setItem("screen", screen);
}, [screen]);

useEffect(() => {

  if (
    window.location.hash === "#accommodationDashboard"
  ) {
    setScreen("accommodationDashboard");
  }

}, []);
const [active, setActive] = useState(
  localStorage.getItem("activeMenu") || "dashboard"
);
useEffect(() => {
  localStorage.setItem("activeMenu", active);
}, [active]);

  const [sidebarOpen, setSidebarOpen] = useState(false);
const [activePage] = useState("home");

useEffect(() => {

  window.scrollTo({
    top:0,
    behavior:"smooth"
  });

}, [activePage]);
  // ── Landing ───────────────────────────────────────────────────────────────
  if (screen === "landing") {
    // return <Landing onEnter={() => setScreen("login")} />;
    return <Landing onEnter={() => setScreen("customerLogin")} />;
  }
  // ── Customer Login ─────────────────────────────────────────────────
if (screen === "customerLogin") {
  return (
    <CustomerLogin
      onSuccess={() => setScreen("customer_dashboard")}
      onRegister={() => setScreen("customerRegister")}
      onAdmin={() => setScreen("login")}

      onGuide={() => setScreen("guideLogin")}
      onVehicle={() => setScreen("vehicleLogin")}
      onDriver={() => setScreen("driverLogin")}
       onAccommodation={() =>
    setScreen("accommodationLogin")
  }
      onBack={() => setScreen("landing")}
    />
  );
}
if (screen === "customer_dashboard") {
  return <PilgrimHome />;
}

if (screen === "aiassistant") {

  return (

    <AIAssistant
      setActivePage={setScreen}
    />

  );

}
/* GUIDE LOGIN */
/* GUIDE LOGIN */

if (screen === "guideLogin") {
  return (
    <TourGuideLogin
      onSuccess={() => setScreen("guideDashboard")}

      onRegister={() => setScreen("guideRegister")}

      onBack={() => setScreen("customerLogin")}
    />
  );
}


if (screen === "guideDashboard") {
  return <TouriestGuide onBack={() => setScreen("guideLogin")} />;
}

/* GUIDE REGISTER */

if (screen === "guideRegister") {
  return (
    <TourGuideRegistration

      onLogin={() => setScreen("guideLogin")}

      onBack={() => setScreen("customerLogin")}
    />
  );
}

/* VEHICLE LOGIN */

if (screen === "vehicleLogin") {
  return (
    <VehicleLogin

      onSuccess={() => setScreen("vehicleDashboard")}

      onRegister={() => setScreen("vehicleRegister")}

      onBack={() => setScreen("customerLogin")}
    />
  );
}

if (screen === "vehicleDashboard") {
  return <VahicleLoginDetails onBack={() => setScreen("vehicleLogin")} />;
}

/* VEHICLE REGISTER */

if (screen === "vehicleRegister") {
  return (
    <VehicleRegistration

      onLogin={() => setScreen("vehicleLogin")}

      onBack={() => setScreen("customerLogin")}
    />
  );
}
/* ACCOMMODATION LOGIN */

if (screen === "accommodationLogin") {

  return (

    <AccommodationLogin

      onSuccess={() =>
        setScreen("accommodationDashboard")
      }

      onRegister={() =>
        setScreen("accommodationRegister")
      }

      onBack={() =>
        setScreen("customerLogin")
      }

    />

  );

}


/* ACCOMMODATION DASHBOARD */

if (screen === "accommodationDashboard") {

  return (
    <AccommodationLoginDetails
      onBack={() =>
        setScreen("accommodationLogin")
      }
    />
  );

}


/* ACCOMMODATION REGISTER */

if (screen === "accommodationRegister") {

  return (

    <AccommodationRegistration

      onLogin={() =>
        setScreen("accommodationLogin")
      }

      onBack={() =>
        setScreen("customerLogin")
      }

    />

  );

}

/* DRIVER LOGIN */

if (screen === "driverLogin") {
  return (
    <DriverLogin

      onSuccess={() => setScreen("driverDashboard")}

      onRegister={() => setScreen("driverRegister")}

      onBack={() => setScreen("customerLogin")}
    />
  );
}

if (screen === "driverDashboard") {
  return <DriverLoginDetails onBack={() => setScreen("driverLogin")} />;
}

/* DRIVER REGISTER */

if (screen === "driverRegister") {
  return (
    <DriverManagement

      onLogin={() => setScreen("driverLogin")}

      onBack={() => setScreen("customerLogin")}
    />
  );
}
  // ── Login ─────────────────────────────────────────────────────────────────
  if (screen === "login") {
    return (
      <Login
        onSuccess={() => setScreen("app")}
        onRegister={() => setScreen("register")}
        onBack={() => setScreen("landing")} 
      />
    );
  }

  // ── Register ──────────────────────────────────────────────────────────────
  if (screen === "register") {
    return (
      <Register
        onBack={() => setScreen("login")}
        onBackToLanding={() => setScreen("landing")} 
      />
    );
  }
  // ── Customer Register ──────────────────────────────────────────────
if (screen === "customerRegister") {
  return (
    <CustomerRegister
      onBack={() => setScreen("customerLogin")}
      onBackToLanding={() => setScreen("landing")}
    />
  );
}

  // ── Main App Shell ────────────────────────────────────────────────────────
  const content = SCREEN_MAP[active] || (
    <div style={{ padding: 40, color: "#b5860d", fontFamily: "'DM Sans', sans-serif" }}>
      <div style={{ fontSize: 32, marginBottom: 8 }}>🚧</div>
      <div style={{ fontSize: 18, fontWeight: 500 }}>{TITLES[active]}</div>
      <div style={{ color: "#999", marginTop: 8, fontSize: 13 }}>This screen is under construction.</div>
    </div>
  );

  return (
    <div className="app-shell">
      {/* Sidebar */}
      <aside className={`sidebar ${sidebarOpen ? "active" : ""}`}>
        <div className="sb-logo">
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div className="sb-logo-icon">
              <i className="ti ti-om" style={{ fontSize: 16, color: "#1a0a00" }} />
            </div>
            <div>
              <div className="sb-logo-title">Rama Janma Bhumi</div>
              <div className="sb-logo-sub">Admin Portal</div>
            </div>
          </div>
        </div>

        <nav className="sb-nav">
          {NAV.map((group) => (
            <div key={group.section} className="sb-group">
              <div className="sb-label">{group.section}</div>
              {group.items.map((item) => (
                <button
                  key={item.key}
                  className={`sb-item ${active === item.key ? "active" : ""}`}
                  onClick={() => {
  setActive(item.key);

  if (window.innerWidth <= 768) {
    setSidebarOpen(false);
  }
}}
                >
                  
                  <i className={`ti ${item.icon}`} />
                  <span>{item.label}</span>
                  {item.badge && <span className="sb-badge">{item.badge}</span>}
                </button>
              ))}
              <div className="sb-divider" />
            </div>
          ))}
        </nav>

        <div className="sb-footer">
          <div className="sb-avatar" />
          <div>
            <div className="sb-user-name">Admin User</div>
            <div className="sb-user-role">Super Admin</div>
          </div>
          {/* Logout */}
          <button
            title="Logout"
          onClick={() => {
  localStorage.removeItem("screen");
  localStorage.removeItem("activeMenu");
  setScreen("customerLogin");
  setActive("dashboard");
}}
            style={{
              marginLeft: "auto", background: "none", border: "none",
              cursor: "pointer", color: "#b5860d", fontSize: 16, padding: 4,
            }}
          >
            <i className="ti ti-logout" />
          </button>
        </div>
      </aside>

      {/* Main */}
      <div className="main-area">
        <header className="topbar">

  <button
    className="menu-toggle"
    onClick={() => setSidebarOpen(!sidebarOpen)}
  >
    <i className="ti ti-menu-2"></i>
  </button>

  
          {/* <div className="tb-title">{TITLES[active]}</div> */}
          <div className="tb-search">
            <i className="ti ti-search" style={{ fontSize: 14 }} />
            <span>Search pilgrims, vehicles, guides…</span>
          </div>
          <div style={{ fontSize: 11, color: "#888" }}>Fri, 15 May 2026</div>
          <div className="tb-icon-btn">
            <i className="ti ti-bell" style={{ fontSize: 15, color: "#888" }} />
            <div className="tb-dot" />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {/* <div className="tb-user-avatar" /> */}
            <div style={{ fontSize: 11, fontWeight: 500, color: "#1a0a00" }}>Super Admin</div>
          </div>
        </header>

        <div className="page-content">{content}</div>
      </div>
    </div>
  );
}
